package main

import (
	"encoding/json"
	"sort"
	"strings"
)

type chalkRow struct {
	I int `json:"i"`
	Verb string `json:"verb"`
	Plate string `json:"plate"`
	Deck string `json:"deck,omitempty"`
	Lane string `json:"lane,omitempty"`
	Station string `json:"station,omitempty"`
	OK string `json:"ok"`
}

func fold(sheet string) (int, string) {
	cars, rc := parseRoll(sheet)
	if rc != 0 { return rc, "" }
	if len(cars) == 0 { return 0, "" }
	ordered := arrange(cars)
	fill := make(map[string]*occ)
	deckKg := make(map[string]int)
	for i := range ordered {
		car := &ordered[i]
		lane, need, station, ok := pickLane(*car, fill, deckKg)
		if !ok { continue }
		car.OK, car.Deck, car.Lane, car.Station = true, lane.Deck, lane.Name, station
		slot := fill[lane.Name]
		if slot == nil { slot = &occ{}; fill[lane.Name] = slot }
		slot.used += need
		slot.mass += car.Mass
		slot.lastHaz = car.Haz
		slot.has = true
		deckKg[lane.Deck] += car.Mass
	}
	sort.Slice(ordered, func(i,j int) bool { return ordered[i].Index < ordered[j].Index })
	var out strings.Builder
	for i, car := range ordered {
		row := chalkRow{I:i+1, Verb:"stow", Plate:car.Plate, OK:"no"}
		if car.OK {
			row.OK, row.Deck, row.Lane, row.Station = "yes", car.Deck, car.Lane, fmtInt(car.Station)
		}
		b, _ := json.Marshal(row)
		out.Write(b); out.WriteByte('\n')
	}
	return 0, out.String()
}

func fmtInt(n int) string {
	if n == 0 { return "0" }
	const digits = "0123456789"
	var b [32]byte; p := len(b)
	for n > 0 { p--; b[p] = digits[n%10]; n /= 10 }
	return string(b[p:])
}
